// shadcn Input class string, copied from registry/input-text/input-text.svelte for standalone Auth.Input.
export const AUTH_INPUT_CLASS =
	'border-input focus-visible:border-ring focus-visible:ring-ring/50 aria-invalid:ring-destructive/20 dark:aria-invalid:ring-destructive/40 aria-invalid:border-destructive dark:bg-input/30 h-9 w-full min-w-0 rounded-md border bg-transparent px-2.5 py-1 text-base shadow-xs transition-[color,box-shadow] outline-none placeholder:text-muted-foreground disabled:pointer-events-none disabled:cursor-not-allowed disabled:opacity-50 md:text-sm'

import type { AuthMessages } from './types.js'

// Default, overridable error copy. Codes come from the SDK auth remotes' AuthResult.
export const loginMessages: AuthMessages = {
	invalid_credentials: 'Invalid email or password.',
	rate_limited: 'Too many attempts. Please wait a moment and try again.',
	unsupported: 'This account needs an extra sign-in step that is not supported yet.',
	unknown: 'Something went wrong. Please try again.'
}
export const registerMessages: AuthMessages = {
	email_exists: 'An account with that email already exists.',
	unsupported: 'This sign-up needs an extra step that is not supported yet.',
	unknown: 'Something went wrong. Please try again.'
}
export const resetMessages: AuthMessages = {
	unknown: 'Something went wrong. Please try again.'
}
export function resolveMessage(messages: AuthMessages, code: string | undefined): string {
	return (
		messages[code ?? 'unknown'] ?? messages.unknown ?? 'Something went wrong. Please try again.'
	)
}

import type { RemoteForm, RemoteFormInput } from '@sveltejs/kit'
import { setAuthFormContext } from './ctx.svelte.js'
import { resolveMessage } from './auth-messages.js'
import type { AuthForm, AuthMessages, AuthResult } from './types.js'

export interface CreateAuthFormOptions<Input extends RemoteFormInput | void> {
	/** The SDK remote form this component drives (e.g. `login`, `register`). */
	form: RemoteForm<Input, AuthResult>
	/** Default + overridable error copy, keyed by the result `code`. */
	messages: AuthMessages
	/** Runs on a successful (ok) result before `onsuccess` — e.g. `() => getCustomer().refresh()`. */
	onOk?: () => void | Promise<void>
	onsuccess?: () => void
	onswitch?: (mode: string) => void
	onerror?: (result: AuthResult) => void
}

/**
 * Shared wiring for the `Auth.*Form` roots: provides the form context the field/submit parts read,
 * runs the native remote-form submission, maps failure codes to copy, and exposes the enhanced
 * `<form>` attributes. Call it once from a form component's top-level script (component-init scope,
 * so the context is set correctly). Pass a thunk so prop reads stay reactive.
 */
export function createAuthForm<Input extends RemoteFormInput | void>(
	options: () => CreateAuthFormOptions<Input>
) {
	let error = $state('')

	setAuthFormContext({
		// SvelteKit types RemoteForm invariantly in its input shape; this single bridge cast lets any
		// concrete form live in the shared, form-agnostic context the field parts read.
		get form() {
			return options().form as unknown as AuthForm
		},
		get error() {
			return error
		},
		get submitting() {
			return options().form.pending > 0
		},
		get messages() {
			return options().messages
		},
		switchMode: (m) => options().onswitch?.(m)
	})

	const enhanced = options().form.enhance(async ({ submit }) => {
		error = ''
		await submit()
		const o = options()
		const r = o.form.result
		if (r?.ok) {
			await o.onOk?.()
			o.onsuccess?.()
		} else if (r) {
			error = resolveMessage(o.messages, r.code)
			o.onerror?.(r)
		}
	})

	return {
		/** Spread onto the `<form>` element. */
		get enhanced() {
			return enhanced
		},
		/** Clear the form-level error (wire to the form's `oninput`). */
		clearError() {
			error = ''
		}
	}
}

import { getContext, setContext } from 'svelte'
import type { AuthFormContext, AuthFieldContext } from './types.js'

const FORM = Symbol('auth-form')
const FIELD = Symbol('auth-field')

export function setAuthFormContext(ctx: AuthFormContext) {
	setContext(FORM, ctx)
}
export function getAuthFormContext(): AuthFormContext {
	const ctx = getContext<AuthFormContext>(FORM)
	if (!ctx) throw new Error('Auth.* must be used within an Auth.*Form')
	return ctx
}
export function getAuthFormContextOptional(): AuthFormContext | null {
	return getContext<AuthFormContext>(FORM) ?? null
}
export function setAuthFieldContext(ctx: AuthFieldContext) {
	setContext(FIELD, ctx)
}
export function getAuthFieldContext(): AuthFieldContext {
	const ctx = getContext<AuthFieldContext>(FIELD)
	if (!ctx) throw new Error('Auth.Label/Input/Error must be used within <Auth.Field>')
	return ctx
}
export function getAuthFieldContextOptional(): AuthFieldContext | null {
	return getContext<AuthFieldContext>(FIELD) ?? null
}

import type { RemoteForm, RemoteFormField } from '@sveltejs/kit'

// Mirrors the SDK's AuthResult (auth.remote.ts). Codes vary by form.
export type AuthResult = { ok: boolean; code?: string }

export type AuthMessages = Record<string, string>

export type AuthForm = RemoteForm<any, AuthResult>

export type AuthFormContext = {
	readonly form: AuthForm
	readonly error: string
	readonly submitting: boolean
	readonly messages: AuthMessages
	switchMode?: (mode: string) => void
}
export type AuthFieldContext = {
	readonly field: RemoteFormField<any>
	readonly name: string
}
